        createDoc("req-i1", "doc-i-other", List.of("en"), List.of(seg("s1", "Hello")))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("REQUEST_CONFLICT"));
    }

    @Test
    void 增段落_草稿版本加一_重复段落409() throws Exception {
