        approve("doc-a", "s1", "en", "req-a9", 2, 2, "carol")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.sourceVersion").value(2))
                .andExpect(jsonPath("$.translationVersion").value(2));
    }

    @Test
